select u.user_id, u.org_id, u.nick_name, u.user_name, u.user_type, u.email, u.avatar, u.phonenumber, u.sex, u.status, u.del_flag,u.auth_status,u.user_sources, u.login_ip, u.login_date, u.create_time, u.remark, u.wx_code,u.school,u.school_name,o.org_name, o.responsible_per from sys_user u left join sys_org o on u.org_id = o.org_id where u.del_flag = '0'
AND u.user_id = #{userId}
AND u.user_name like concat('%', #{userName}, '%')
AND u.nick_name like concat('%', #{nickName}, '%')
AND u.email like concat('%', #{email}, '%')
AND u.status = #{status}
AND u.sex = #{sex}
AND u.phonenumber like concat('%', #{phonenumber}, '%')
AND u.auth_status = #{authStatus}
AND date_format(u.create_time,'%Y%m%d') >= date_format(#{params.beginTime},'%Y%m%d')
AND date_format(u.create_time,'%Y%m%d') <= date_format(#{params.endTime},'%Y%m%d')
AND (u.org_id = #{orgId} OR u.org_id IN ( SELECT t.org_id FROM sys_org t WHERE find_in_set(#{orgId}, ancestors) ))
${params.dataScope}

SELECT DISTINCT u.user_id, u.org_id, u.nick_name, u.user_name, u.user_type, u.email, u.avatar, u.phonenumber, u.sex, u.status, u.remark, u.wx_code,u.user_sources, a.auth_status,i.certification_type, a.real_name, i.position,i.institute,nci.school_name FROM sys_user u LEFT JOIN identity_info i1 ON i1.user_id = u.user_id AND i1.del_flag = '0' AND i1.check_status = '6' LEFT JOIN identity_info i2 ON u.sys_user_id IS NOT NULL AND u.sys_user_id != '' AND u.sys_user_id != '0' AND i2.user_id = u.sys_user_id AND i2.del_flag = '0' AND i2.check_status = '6' LEFT JOIN identity_info i ON COALESCE(i1.user_id, i2.user_id) IS NOT NULL AND i.user_id = COALESCE(i1.user_id, i2.user_id) LEFT JOIN nationwide_college_info nci ON nci.id= i.school LEFT JOIN auth_info a ON a.auth_id = ( SELECT ai.auth_id FROM auth_info ai WHERE ai.user_id = u.user_id ORDER BY ai.auth_time DESC, ai.auth_id DESC LIMIT 1 ) WHERE u.del_flag = '0'
AND u.user_id = #{userId}
AND u.user_name like concat('%', #{userName}, '%')
AND u.nick_name like concat('%', #{nickName}, '%')
AND u.email like concat('%', #{email}, '%')
AND u.sex = #{sex}
AND u.user_sources = #{userSources}
AND u.phonenumber like concat('%', #{phonenumber}, '%')
AND nci.school_name like concat('%', #{schoolName},'%')
AND i.position like concat('%', #{position},'%')
AND date_format(u.create_time,'%Y%m%d') >= date_format(#{params.beginTime},'%Y%m%d')
AND date_format(u.create_time,'%Y%m%d') <= date_format(#{params.endTime},'%Y%m%d')
AND (u.org_id = #{orgId} OR u.org_id IN ( SELECT t.org_id FROM sys_org t WHERE find_in_set(#{orgId}, ancestors) ))
AND a.auth_status = #{authStatus}
AND u.user_type=#{userType}
AND u.status = #{status}

select distinct u.user_id, u.org_id, u.user_name, u.nick_name, u.email, u.phonenumber, u.status, u.create_time from sys_user u left join sys_org o on u.org_id = o.org_id left join sys_user_role ur on u.user_id = ur.user_id left join sys_role r on r.role_id = ur.role_id where u.del_flag = '0' and r.role_id = #{roleId}
AND u.user_name like concat('%', #{userName}, '%')
AND u.nick_name like concat('%', #{nickName}, '%')
AND u.phonenumber like concat('%', #{phonenumber}, '%')
${params.dataScope}

